-- Post-final-approval physical gate exit. Existing departure/approval history is not rewritten.
INSERT INTO permissions(code) SELECT unnest(ARRAY['gate:read','gate:issue','gate:print','gate:exit','printer:manage']) ON CONFLICT DO NOTHING;
INSERT INTO roles(code,name,name_en,built_in) VALUES('sales_manager','销售经理','Sales Manager',false),('sales_operator','销售业务员','Sales Operator',false);
INSERT INTO role_permission_caps SELECT r,p FROM unnest(ARRAY['sales_manager','sales_operator']) r CROSS JOIN unnest(ARRAY['dashboard:read','master:read','inventory:read','customer:read','plan:read','loading-plan:read','vehicle-arrival:read','load:read','outbound:read','report:read','co:read','gate:read','gate:issue','gate:print','gate:exit']) p;
INSERT INTO role_permission_caps VALUES('sales_manager','printer:manage');
INSERT INTO role_permissions SELECT role_code,permission_code FROM role_permission_caps WHERE role_code IN('sales_manager','sales_operator');
INSERT INTO role_permission_caps SELECT 'admin',code FROM permissions WHERE code LIKE 'gate:%' OR code='printer:manage' ON CONFLICT DO NOTHING;
INSERT INTO role_permissions SELECT role_code,permission_code FROM role_permission_caps WHERE role_code='admin' ON CONFLICT DO NOTHING;
CREATE SEQUENCE gate_permit_numbers;
CREATE TABLE gate_permits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_code text NOT NULL CHECK(product_code IN('CU_CATHODE','CO_HYDROXIDE')),cu_loading_id uuid UNIQUE REFERENCES loading_orders(id),co_order_id uuid UNIQUE REFERENCES co_loading_orders(id),project_id uuid NOT NULL REFERENCES projects(id),customer_id uuid NOT NULL REFERENCES customers(id),document_no text NOT NULL UNIQUE,state text NOT NULL DEFAULT 'READY' CHECK(state IN('READY','EXITED')),current_revision integer NOT NULL DEFAULT 1 CHECK(current_revision>0),version integer NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK((product_code='CU_CATHODE' AND cu_loading_id IS NOT NULL AND co_order_id IS NULL) OR(product_code='CO_HYDROXIDE' AND co_order_id IS NOT NULL AND cu_loading_id IS NULL)));
CREATE TABLE gate_permit_revisions(permit_id uuid NOT NULL REFERENCES gate_permits(id),revision integer NOT NULL CHECK(revision>0),snapshot jsonb NOT NULL,template_sha256 text NOT NULL CHECK(length(template_sha256)=64),file_sha256 text NOT NULL CHECK(length(file_sha256)=64),html_sha256 text NOT NULL CHECK(length(html_sha256)=64),content bytea NOT NULL,print_html text NOT NULL,reason text NOT NULL,generated_by uuid NOT NULL REFERENCES users(id),generated_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(permit_id,revision));
CREATE TABLE gate_printers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),project_id uuid NOT NULL REFERENCES projects(id),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 160),queue_name text NOT NULL CHECK(length(queue_name) BETWEEN 1 AND 240),paper_size text NOT NULL DEFAULT 'A4' CHECK(paper_size IN('A4','A5','Letter')),orientation text NOT NULL DEFAULT 'portrait' CHECK(orientation IN('portrait','landscape')),active boolean NOT NULL DEFAULT true,version integer NOT NULL DEFAULT 1 CHECK(version>0),updated_by uuid NOT NULL REFERENCES users(id),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(project_id,name));
CREATE TABLE gate_print_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),permit_id uuid NOT NULL,revision integer NOT NULL,printer_id uuid REFERENCES gate_printers(id),actor_id uuid NOT NULL REFERENCES users(id),requested_at timestamptz NOT NULL DEFAULT clock_timestamp(),state text NOT NULL CHECK(state='DIALOG_REQUESTED'),FOREIGN KEY(permit_id,revision) REFERENCES gate_permit_revisions(permit_id,revision));
CREATE TABLE gate_exits(permit_id uuid PRIMARY KEY REFERENCES gate_permits(id),revision integer NOT NULL,actual_exit_at timestamptz NOT NULL,confirmed_by uuid NOT NULL REFERENCES users(id),confirmed_at timestamptz NOT NULL DEFAULT clock_timestamp(),note text NOT NULL DEFAULT '',FOREIGN KEY(permit_id,revision) REFERENCES gate_permit_revisions(permit_id,revision));
CREATE TABLE gate_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,permit_id uuid REFERENCES gate_permits(id),actor_id uuid NOT NULL REFERENCES users(id),action text NOT NULL,before_data jsonb,after_data jsonb,occurred_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE gate_requests(actor_id uuid NOT NULL REFERENCES users(id),product_code text NOT NULL,route text NOT NULL,key text NOT NULL,request_hash text NOT NULL,response jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(actor_id,product_code,route,key));
CREATE FUNCTION gate_source_ready(p gate_permits) RETURNS boolean LANGUAGE plpgsql STABLE AS $$BEGIN
 IF p.product_code='CO_HYDROXIDE' THEN RETURN EXISTS(SELECT 1 FROM co_loading_orders l JOIN co_load_executions e ON e.order_id=l.id JOIN co_outbounds o ON o.order_id=l.id JOIN co_sales_plans sp ON sp.id=l.sales_plan_id WHERE l.id=p.co_order_id AND l.status='OUTBOUND' AND e.state='OUTBOUND' AND sp.project_id=p.project_id AND sp.customer_id=p.customer_id);END IF;
 RETURN EXISTS(SELECT 1 FROM loading_orders l WHERE l.id=p.cu_loading_id AND l.project_id=p.project_id AND l.customer_id=p.customer_id AND l.status='DEPARTED' AND(l.workflow_state='OUTBOUND' AND l.manager_at IS NOT NULL OR l.workflow_state IS NULL AND EXISTS(SELECT 1 FROM outbound_orders o WHERE o.loading_id=l.id AND o.status='DEPARTED' AND o.reversal_status<>'CONFIRMED')) AND NOT EXISTS(SELECT 1 FROM outbound_corrections cr WHERE cr.loading_id=l.id AND cr.kind='RETURN_OUTBOUND' AND cr.status IN('REQUESTED','AUTHORIZED','RETURN_VERIFIED','APPLIED')));
END$$;
CREATE FUNCTION gate_actor_scope(p gate_permits,actor uuid) RETURNS boolean LANGUAGE plpgsql STABLE AS $$BEGIN
 IF p.product_code='CO_HYDROXIDE' THEN RETURN EXISTS(SELECT 1 FROM co_loading_orders l JOIN co_sales_plans sp ON sp.id=l.sales_plan_id JOIN user_scopes s ON s.project_id=sp.project_id AND s.user_id=actor AND(s.warehouse_id IS NULL OR s.warehouse_id=sp.warehouse_id) AND(s.customer_id IS NULL OR s.customer_id=sp.customer_id) WHERE l.id=p.co_order_id);END IF;
 RETURN EXISTS(SELECT 1 FROM user_scopes s WHERE s.user_id=actor AND s.project_id=p.project_id AND(s.customer_id IS NULL OR s.customer_id=p.customer_id)) AND NOT EXISTS(SELECT 1 FROM loading_items i JOIN locations loc ON loc.id=i.original_location_id WHERE i.loading_id=p.cu_loading_id AND NOT EXISTS(SELECT 1 FROM user_scopes s WHERE s.user_id=actor AND s.project_id=p.project_id AND(s.warehouse_id IS NULL OR s.warehouse_id=loc.warehouse_id) AND(s.customer_id IS NULL OR s.customer_id=p.customer_id)));
END$$;
CREATE FUNCTION gate_permit_guard() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'GATE_HISTORY_IMMUTABLE' USING ERRCODE='23514';END IF;
 IF TG_OP='UPDATE' THEN IF to_jsonb(NEW)-ARRAY['version','state','current_revision']<>to_jsonb(OLD)-ARRAY['version','state','current_revision'] OR OLD.state='EXITED' OR NEW.version<>OLD.version+1 OR NEW.current_revision NOT IN(OLD.current_revision,OLD.current_revision+1) THEN RAISE EXCEPTION 'GATE_IDENTITY_IMMUTABLE' USING ERRCODE='23514';END IF;END IF;
 IF NOT gate_actor_scope(NEW,NEW.created_by) OR NOT gate_source_ready(NEW) THEN RAISE EXCEPTION 'GATE_FINAL_APPROVAL_REQUIRED' USING ERRCODE='23514';END IF;RETURN NEW;
END$$;
CREATE TRIGGER gate_permit_identity BEFORE INSERT OR UPDATE OR DELETE ON gate_permits FOR EACH ROW EXECUTE FUNCTION gate_permit_guard();
CREATE FUNCTION gate_exit_guard() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE p gate_permits;stamp timestamptz;BEGIN
 SELECT * INTO p FROM gate_permits WHERE id=NEW.permit_id FOR UPDATE;
 IF p.state<>'READY' OR NOT gate_source_ready(p) OR NOT gate_actor_scope(p,NEW.confirmed_by) OR NEW.revision<>p.current_revision THEN RAISE EXCEPTION 'GATE_EXIT_STATE' USING ERRCODE='23514';END IF;
 IF NOT EXISTS(SELECT 1 FROM users u JOIN role_permissions rp ON rp.role_code=u.role_code WHERE u.id=NEW.confirmed_by AND u.active AND u.deleted_at IS NULL AND u.role_code IN('sales_manager','sales_operator') AND rp.permission_code='gate:exit') THEN RAISE EXCEPTION 'GATE_SALES_REQUIRED' USING ERRCODE='23514';END IF;
 SELECT generated_at INTO stamp FROM gate_permit_revisions WHERE permit_id=p.id AND revision=NEW.revision;
 IF NEW.actual_exit_at<stamp OR NEW.actual_exit_at>clock_timestamp()+interval '1 minute' OR NOT EXISTS(SELECT 1 FROM gate_print_jobs WHERE permit_id=p.id AND revision=NEW.revision) THEN RAISE EXCEPTION 'GATE_PRINT_AND_ACTUAL_TIME_REQUIRED' USING ERRCODE='23514';END IF;RETURN NEW;
END$$;
CREATE TRIGGER gate_exit_validate BEFORE INSERT ON gate_exits FOR EACH ROW EXECUTE FUNCTION gate_exit_guard();
CREATE FUNCTION gate_complete_guard() RETURNS trigger LANGUAGE plpgsql AS $$DECLARE p gate_permits;BEGIN IF TG_TABLE_NAME='gate_permits' THEN SELECT * INTO p FROM gate_permits WHERE id=NEW.id;ELSE SELECT * INTO p FROM gate_permits WHERE id=NEW.permit_id;END IF;IF NOT EXISTS(SELECT 1 FROM gate_permit_revisions WHERE permit_id=p.id AND revision=p.current_revision) OR (p.state='EXITED')<>EXISTS(SELECT 1 FROM gate_exits WHERE permit_id=p.id) THEN RAISE EXCEPTION 'GATE_DOCUMENT_EXIT_INTEGRITY' USING ERRCODE='23514';END IF;RETURN NULL;END$$;
CREATE CONSTRAINT TRIGGER gate_complete_permit AFTER INSERT OR UPDATE ON gate_permits DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION gate_complete_guard();
CREATE CONSTRAINT TRIGGER gate_complete_exit AFTER INSERT ON gate_exits DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION gate_complete_guard();
CREATE FUNCTION gate_history_immutable() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'GATE_HISTORY_IMMUTABLE' USING ERRCODE='23514';END$$;
CREATE TRIGGER gate_revision_immutable BEFORE UPDATE OR DELETE ON gate_permit_revisions FOR EACH ROW EXECUTE FUNCTION gate_history_immutable();
CREATE TRIGGER gate_exit_immutable BEFORE UPDATE OR DELETE ON gate_exits FOR EACH ROW EXECUTE FUNCTION gate_history_immutable();
CREATE TRIGGER gate_event_immutable BEFORE UPDATE OR DELETE ON gate_events FOR EACH ROW EXECUTE FUNCTION gate_history_immutable();
CREATE TRIGGER gate_job_immutable BEFORE UPDATE OR DELETE ON gate_print_jobs FOR EACH ROW EXECUTE FUNCTION gate_history_immutable();
CREATE TRIGGER gate_request_immutable BEFORE UPDATE OR DELETE ON gate_requests FOR EACH ROW EXECUTE FUNCTION gate_history_immutable();
GRANT SELECT,INSERT,UPDATE ON gate_permits,gate_printers TO musonoi_app;
GRANT SELECT,INSERT ON gate_permit_revisions,gate_print_jobs,gate_exits,gate_events,gate_requests TO musonoi_app;
GRANT USAGE,SELECT ON SEQUENCE gate_permit_numbers,gate_events_id_seq TO musonoi_app;
